import React, { useState } from "react"
import { Link } from "gatsby"
import ProjectCard from "./ProjectCard"

const FILTERS = [
  { id: "all", label: "All Stories" },
  { id: "game", label: "Games" },
  { id: "app", label: "Apps" },
  { id: "motion", label: "Motion" },
]

const FILTER_COPY = {
  all: "A cross-section of games, practical tools, and motion sketches arranged like a weekend feature section.",
  game: "Playable experiments with arcade energy, tuned for quick curiosity and repeat visits.",
  app: "Useful browser tools presented with more warmth, texture, and editorial framing.",
  motion:
    "Visual studies that behave more like animated cover stories than simple demos.",
}

const EDITORIAL_PRIORITY = {
  "motion-1": 0,
  "game-2": 1,
  "game-1": 2,
  "app-2": 3,
  "motion-2": 4,
  "app-1": 5,
  "app-3": 6,
}

const delayClassForIndex = index => {
  const delayClasses = [
    "",
    "stagger-delay-1",
    "stagger-delay-2",
    "stagger-delay-3",
  ]
  return delayClasses[index % delayClasses.length]
}

const formatCount = count => String(count).padStart(2, "0")

const ProjectList = ({ projects }) => {
  const [searchTerm, setSearchTerm] = useState("")
  const [activeFilter, setActiveFilter] = useState("all")

  const normalizedSearchTerm = searchTerm.trim().toLowerCase()

  const filteredProjects = projects.filter(project => {
    const matchesSearch =
      project.title.toLowerCase().includes(normalizedSearchTerm) ||
      project.description.toLowerCase().includes(normalizedSearchTerm)

    const matchesFilter =
      activeFilter === "all" || project.type === activeFilter

    return matchesSearch && matchesFilter
  })

  const editorialProjects = [...filteredProjects].sort(
    (left, right) =>
      (EDITORIAL_PRIORITY[left.id] ?? Number.MAX_SAFE_INTEGER) -
      (EDITORIAL_PRIORITY[right.id] ?? Number.MAX_SAFE_INTEGER)
  )

  const countsByFilter = {
    all: projects.length,
    game: projects.filter(project => project.type === "game").length,
    app: projects.filter(project => project.type === "app").length,
    motion: projects.filter(project => project.type === "motion").length,
  }

  const issueDate = new Intl.DateTimeFormat("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric",
  }).format(new Date())
  const issueMonth = new Intl.DateTimeFormat("en-US", {
    month: "long",
  }).format(new Date())

  const highlightedProjects = (
    editorialProjects.length > 0 ? editorialProjects : projects
  ).slice(0, 3)
  const leadProject = editorialProjects[0]
  const secondaryProjects = editorialProjects.slice(1, 3)
  const mosaicProjects = editorialProjects.slice(3)

  return (
    <div className="mx-auto max-w-7xl px-4 pb-16 pt-6 sm:px-6 lg:px-8 lg:pb-20 lg:pt-8">
      <section className="grid gap-6 lg:grid-cols-[1.35fr_0.92fr]">
        <div className="paper-panel stagger-in overflow-hidden rounded-[2.25rem] p-8 sm:p-10 lg:p-12">
          <div className="relative z-10">
            <p className="section-kicker">
              {issueMonth} Issue / {issueDate}
            </p>
            <div className="mt-8 grid gap-8 xl:grid-cols-[1.28fr_0.72fr]">
              <div>
                <p className="headline-display max-w-4xl text-[clamp(3.25rem,9vw,6.75rem)] text-[var(--ink)]">
                  A personal project shelf, art directed like a small magazine.
                </p>
                <p className="mt-6 max-w-2xl text-base leading-7 text-[var(--muted)] sm:text-lg">
                  {FILTER_COPY[activeFilter]}
                </p>
                <div className="mt-8 flex flex-wrap gap-3">
                  {[
                    { label: "Stories", value: formatCount(projects.length) },
                    { label: "Games", value: formatCount(countsByFilter.game) },
                    { label: "Apps", value: formatCount(countsByFilter.app) },
                    {
                      label: "Motion",
                      value: formatCount(countsByFilter.motion),
                    },
                  ].map(item => (
                    <div
                      key={item.label}
                      className="paper-inset rounded-full px-4 py-3 text-center"
                    >
                      <p className="text-xs font-semibold uppercase tracking-[0.22em] text-[var(--muted)]">
                        {item.label}
                      </p>
                      <p className="headline-serif mt-1 text-2xl text-[var(--ink)]">
                        {item.value}
                      </p>
                    </div>
                  ))}
                </div>
                <div className="mt-10 flex flex-wrap gap-4">
                  <a
                    href="#stories"
                    className="editorial-link paper-panel rounded-full px-6 py-3 text-sm font-semibold text-[var(--ink)]"
                  >
                    Browse the Spread
                  </a>
                  {leadProject ? (
                    <Link
                      to={leadProject.demoUrl}
                      state={{ isFullscreen: false }}
                      className="editorial-link rounded-full border border-[var(--line-strong)] px-6 py-3 text-sm font-semibold text-[var(--ink)]"
                    >
                      Open Cover Story
                    </Link>
                  ) : null}
                </div>
              </div>

              <div className="paper-inset rounded-[1.8rem] p-6">
                <p className="section-kicker">Editor&apos;s Letter</p>
                <h2 className="headline-serif mt-4 text-3xl leading-tight text-[var(--ink)]">
                  Playful experiments deserve stronger framing than a plain card
                  wall.
                </h2>
                <p className="mt-4 text-sm leading-7 text-[var(--muted)]">
                  This front page now reads like a curated issue: a clear
                  masthead, a featured story, and a rhythm between major pieces
                  and shorter departments.
                </p>
                <div className="mt-6 space-y-4 border-t border-[var(--line)] pt-4">
                  {highlightedProjects.map((project, index) => (
                    <Link
                      key={project.id}
                      to={project.demoUrl}
                      state={{ isFullscreen: false }}
                      className="editorial-link flex items-start justify-between gap-4 border-b border-[var(--line)] pb-4 last:border-b-0 last:pb-0"
                    >
                      <div>
                        <p className="section-kicker !text-[0.62rem]">
                          {project.type} Feature
                        </p>
                        <p className="headline-serif mt-2 text-xl font-semibold text-[var(--ink)]">
                          {project.title}
                        </p>
                      </div>
                      <span className="headline-serif text-2xl text-[var(--line-strong)]">
                        {formatCount(index + 1)}
                      </span>
                    </Link>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>

        <aside className="space-y-6">
          <div className="paper-panel stagger-in stagger-delay-1 rounded-[2rem] p-6">
            <p className="section-kicker">Issue Finder</p>
            <label className="mt-4 block">
              <span className="sr-only">Search projects</span>
              <div className="paper-inset flex items-center gap-3 rounded-full px-4 py-3">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  viewBox="0 0 20 20"
                  fill="currentColor"
                  className="h-5 w-5 text-[var(--muted)]"
                >
                  <path
                    fillRule="evenodd"
                    d="M9 3.5a5.5 5.5 0 1 0 3.49 9.75l3.63 3.63a1 1 0 0 0 1.41-1.42l-3.62-3.62A5.5 5.5 0 0 0 9 3.5ZM5.5 9a3.5 3.5 0 1 1 7 0a3.5 3.5 0 0 1-7 0Z"
                    clipRule="evenodd"
                  />
                </svg>
                <input
                  type="text"
                  placeholder="Search titles or descriptions"
                  value={searchTerm}
                  onChange={event => setSearchTerm(event.target.value)}
                  className="w-full bg-transparent text-sm text-[var(--ink)] outline-none placeholder:text-[var(--muted)]"
                />
              </div>
            </label>

            <div className="mt-5 flex flex-wrap gap-2">
              {FILTERS.map(filter => {
                const isActive = activeFilter === filter.id

                return (
                  <button
                    key={filter.id}
                    type="button"
                    onClick={() => setActiveFilter(filter.id)}
                    aria-pressed={isActive}
                    className={`rounded-full px-4 py-2 text-sm font-semibold transition ${
                      isActive
                        ? "bg-[var(--ink)] text-white"
                        : "paper-inset text-[var(--ink)] hover:-translate-y-0.5"
                    }`}
                  >
                    {filter.label}
                    <span
                      className={`ml-2 ${
                        isActive ? "text-white/70" : "text-[var(--muted)]"
                      }`}
                    >
                      {formatCount(countsByFilter[filter.id])}
                    </span>
                  </button>
                )
              })}
            </div>
          </div>

          {leadProject ? (
            <div className="paper-panel stagger-in stagger-delay-2 rounded-[2rem] p-6">
              <p className="section-kicker">Cover Line</p>
              <h2 className="headline-serif mt-4 text-3xl leading-tight text-[var(--ink)]">
                {leadProject.title}
              </h2>
              <p className="mt-4 text-sm leading-7 text-[var(--muted)]">
                {leadProject.description}
              </p>
              <div className="mt-6 grid grid-cols-3 gap-3">
                {[
                  {
                    label: "Visible",
                    value: formatCount(filteredProjects.length),
                  },
                  {
                    label: "Tagged",
                    value: formatCount(leadProject.tags.length),
                  },
                  { label: "Issue", value: "01" },
                ].map(stat => (
                  <div
                    key={stat.label}
                    className="paper-inset rounded-[1.1rem] px-3 py-4 text-center"
                  >
                    <p className="text-[0.62rem] font-semibold uppercase tracking-[0.22em] text-[var(--muted)]">
                      {stat.label}
                    </p>
                    <p className="headline-serif mt-2 text-2xl text-[var(--ink)]">
                      {stat.value}
                    </p>
                  </div>
                ))}
              </div>
              <Link
                to={leadProject.demoUrl}
                state={{ isFullscreen: false }}
                className="editorial-link mt-6 flex items-center justify-between border-t border-[var(--line)] pt-4 text-sm font-semibold text-[var(--ink)]"
              >
                <span>Open cover story</span>
                <span className="text-[var(--accent-deep)]">Enter</span>
              </Link>
            </div>
          ) : null}
        </aside>
      </section>

      {editorialProjects.length > 0 ? (
        <>
          {leadProject ? (
            <section
              id="stories"
              className={`mt-10 grid gap-6 ${
                secondaryProjects.length > 0
                  ? "lg:grid-cols-[1.15fr_0.85fr]"
                  : ""
              }`}
            >
              <ProjectCard
                project={leadProject}
                variant="lead"
                issueNumber={1}
                className="stagger-in"
              />

              {secondaryProjects.length > 0 ? (
                <div className="grid gap-6">
                  {secondaryProjects.map((project, index) => (
                    <ProjectCard
                      key={project.id}
                      project={project}
                      variant="feature"
                      issueNumber={index + 2}
                      className={`stagger-in ${delayClassForIndex(
                        index + 1
                      )}`.trim()}
                    />
                  ))}
                </div>
              ) : null}
            </section>
          ) : null}

          {mosaicProjects.length > 0 ? (
            <section className="mt-14">
              <div className="mb-6 flex flex-col gap-4 border-t border-[var(--line)] pt-6 lg:flex-row lg:items-end lg:justify-between">
                <div>
                  <p className="section-kicker">Departments</p>
                  <h2 className="headline-serif mt-3 text-4xl text-[var(--ink)]">
                    From the Studio Floor
                  </h2>
                </div>
                <p className="max-w-2xl text-sm leading-7 text-[var(--muted)]">
                  Shorter utilities, playful prototypes, and motion studies
                  continue the issue after the cover section.
                </p>
              </div>

              <div className="grid gap-6 md:grid-cols-2 xl:grid-cols-3">
                {mosaicProjects.map((project, index) => {
                  const spanClass =
                    index === 0 && mosaicProjects.length > 2
                      ? "md:col-span-2 xl:col-span-2"
                      : ""

                  return (
                    <ProjectCard
                      key={project.id}
                      project={project}
                      issueNumber={index + 4}
                      className={`stagger-in ${delayClassForIndex(
                        index
                      )} ${spanClass}`.trim()}
                    />
                  )
                })}
              </div>
            </section>
          ) : null}
        </>
      ) : (
        <section id="stories" className="mt-10">
          <div className="paper-panel rounded-[2rem] p-8 text-center">
            <p className="section-kicker">No Match Found</p>
            <h2 className="headline-serif mt-4 text-4xl text-[var(--ink)]">
              This issue needs a different query.
            </h2>
            <p className="mx-auto mt-4 max-w-xl text-sm leading-7 text-[var(--muted)]">
              No project matched the current search and filter combination.
              Reset the finder to see the full spread again.
            </p>
            <button
              type="button"
              onClick={() => {
                setSearchTerm("")
                setActiveFilter("all")
              }}
              className="editorial-link paper-panel mt-8 rounded-full px-6 py-3 text-sm font-semibold text-[var(--ink)]"
            >
              Reset the Finder
            </button>
          </div>
        </section>
      )}
    </div>
  )
}

export default ProjectList
