import React from "react"
import { Link } from "gatsby"
import { CodeBracketIcon, GamepadIcon, MotionGraphicsIcon } from "./Icons"

const FALLBACK_IMAGE =
  "https://placehold.co/960x720/E7D8C4/241B17?text=Silbaram+Review"

const TYPE_META = {
  app: {
    label: "Utility",
    accent: "#b45a3c",
    Icon: CodeBracketIcon,
  },
  game: {
    label: "Arcade",
    accent: "#1f5f72",
    Icon: GamepadIcon,
  },
  motion: {
    label: "Motion",
    accent: "#8d6a28",
    Icon: MotionGraphicsIcon,
  },
}

const formatIssueNumber = issueNumber =>
  issueNumber ? String(issueNumber).padStart(2, "0") : null

const StoryMeta = ({ project, issueNumber }) => {
  const { label, accent, Icon } = TYPE_META[project.type] ?? TYPE_META.app

  return (
    <div className="flex items-center justify-between gap-4 text-[0.72rem] font-semibold uppercase tracking-[0.28em] text-[var(--muted)]">
      <div className="flex items-center gap-3">
        <div
          className="paper-inset flex h-10 w-10 items-center justify-center rounded-full"
          style={{ color: accent }}
        >
          <Icon />
        </div>
        <span>{label}</span>
      </div>
      {issueNumber ? (
        <span className="text-[var(--line-strong)]">
          No. {formatIssueNumber(issueNumber)}
        </span>
      ) : null}
    </div>
  )
}

const StoryTags = ({ tags }) => (
  <div className="flex flex-wrap gap-2">
    {tags.map(tag => (
      <span
        key={tag}
        className="rounded-full border border-[var(--line)] bg-[rgba(255,255,255,0.7)] px-3 py-1 text-[0.68rem] font-semibold uppercase tracking-[0.22em] text-[var(--muted)]"
      >
        {tag}
      </span>
    ))}
  </div>
)

const ImageBlock = ({ project, className }) => (
  <div className={`overflow-hidden bg-[var(--paper-deep)] ${className}`}>
    <img
      src={project.imageUrl}
      alt={project.title}
      className="h-full w-full object-cover transition duration-700 ease-out group-hover:scale-105"
      onError={event => {
        event.currentTarget.onerror = null
        event.currentTarget.src = FALLBACK_IMAGE
      }}
    />
  </div>
)

const ProjectCard = ({
  project,
  variant = "mosaic",
  issueNumber,
  className = "",
}) => {
  const linkClasses = `group block h-full ${className}`.trim()

  if (variant === "lead") {
    return (
      <Link
        to={project.demoUrl}
        state={{ isFullscreen: false }}
        className={linkClasses}
      >
        <article className="paper-panel h-full overflow-hidden rounded-[2rem] p-4 sm:p-5">
          <div className="grid h-full gap-5 lg:grid-cols-[1.08fr_0.92fr]">
            <div className="relative min-h-[20rem]">
              <ImageBlock
                project={project}
                className="h-full rounded-[1.6rem]"
              />
              <div className="absolute inset-0 rounded-[1.6rem] bg-gradient-to-t from-[rgba(34,24,19,0.5)] via-transparent to-transparent" />
              <div className="absolute bottom-4 left-4 rounded-full bg-[rgba(255,255,255,0.84)] px-4 py-2 text-[0.68rem] font-bold uppercase tracking-[0.3em] text-[var(--accent-deep)]">
                Cover Story
              </div>
            </div>
            <div className="flex flex-col justify-between gap-6 p-3 sm:p-5">
              <div className="space-y-5">
                <StoryMeta project={project} issueNumber={issueNumber} />
                <div className="space-y-4">
                  <h3 className="headline-display text-4xl text-[var(--ink)] sm:text-5xl">
                    {project.title}
                  </h3>
                  <p className="max-w-xl text-sm leading-7 text-[var(--muted)] sm:text-base">
                    {project.description}
                  </p>
                </div>
              </div>
              <div className="space-y-5">
                <StoryTags tags={project.tags} />
                <div className="flex items-center justify-between border-t border-[var(--line)] pt-4 text-sm font-semibold text-[var(--ink)]">
                  <span>Open the feature</span>
                  <span className="inline-block text-[var(--accent)] transition duration-300 group-hover:translate-x-1">
                    Explore
                  </span>
                </div>
              </div>
            </div>
          </div>
        </article>
      </Link>
    )
  }

  if (variant === "feature") {
    return (
      <Link
        to={project.demoUrl}
        state={{ isFullscreen: false }}
        className={linkClasses}
      >
        <article className="paper-panel flex h-full flex-col overflow-hidden rounded-[2rem]">
          <ImageBlock project={project} className="h-60 rounded-t-[2rem]" />
          <div className="flex flex-1 flex-col gap-5 p-6">
            <StoryMeta project={project} issueNumber={issueNumber} />
            <div className="space-y-3">
              <h3 className="headline-serif text-3xl font-semibold leading-tight text-[var(--ink)]">
                {project.title}
              </h3>
              <p className="text-sm leading-7 text-[var(--muted)]">
                {project.description}
              </p>
            </div>
            <div className="mt-auto space-y-4">
              <StoryTags tags={project.tags} />
              <div className="flex items-center justify-between border-t border-[var(--line)] pt-4 text-sm font-semibold text-[var(--ink)]">
                <span>Open story</span>
                <span className="inline-block text-[var(--accent-deep)] transition duration-300 group-hover:translate-x-1">
                  View
                </span>
              </div>
            </div>
          </div>
        </article>
      </Link>
    )
  }

  return (
    <Link
      to={project.demoUrl}
      state={{ isFullscreen: false }}
      className={linkClasses}
    >
      <article className="paper-panel flex h-full flex-col overflow-hidden rounded-[1.75rem]">
        <ImageBlock project={project} className="h-48 rounded-t-[1.75rem]" />
        <div className="flex flex-1 flex-col gap-4 p-5">
          <StoryMeta project={project} issueNumber={issueNumber} />
          <div className="space-y-3">
            <h3 className="headline-serif text-2xl font-semibold leading-tight text-[var(--ink)]">
              {project.title}
            </h3>
            <p className="text-sm leading-6 text-[var(--muted)]">
              {project.description}
            </p>
          </div>
          <div className="mt-auto space-y-4">
            <StoryTags tags={project.tags} />
            <div className="flex items-center justify-between border-t border-[var(--line)] pt-4 text-sm font-semibold text-[var(--ink)]">
              <span>Preview</span>
              <span className="inline-block text-[var(--accent)] transition duration-300 group-hover:translate-x-1">
                Open
              </span>
            </div>
          </div>
        </div>
      </article>
    </Link>
  )
}

export default ProjectCard
